func testAccCheckVertexAITaskStoreDestroyProducer(t *testing.T) func(s *terraform.State) error {
	return func(s *terraform.State) error {
		for name, rs := range s.RootModule().Resources {
			if rs.Type != "google_vertex_ai_task_store" {
				continue
			}
			if strings.HasPrefix(name, "data.") {
				continue
			}

			config := acctest.GoogleProviderConfig(t)

			url, err := tpgresource.ReplaceVarsForTest(config, rs, transport_tpg.BaseUrl(vertexai.Product, config)+"projects/{{project}}/locations/{{region}}/taskStores/{{task_store_id}}")
			if err != nil {
				return err
			}
			// The "global" location is only served by the non-regional endpoint; see
			// vertexAITaskStoreGlobalURL in the resource.
			url = strings.Replace(url, "://global-aiplatform.googleapis.com/", "://aiplatform.googleapis.com/", 1)

			billingProject := ""

			if config.BillingProject != "" {
				billingProject = config.BillingProject
			}

			_, err = transport_tpg.SendRequest(transport_tpg.SendRequestOptions{
				Config:    config,
				Method:    "GET",
				Project:   billingProject,
				RawURL:    url,
				UserAgent: config.UserAgent,
			})
			if err == nil {
				return fmt.Errorf("VertexAITaskStore still exists at %s", url)
			}
			// Only a 404 proves the TaskStore is gone; surface any other error rather
			// than treating it as a successful destroy.
			if !transport_tpg.IsGoogleApiErrorWithCode(err, 404) {
				return fmt.Errorf("error checking whether VertexAITaskStore was destroyed at %s: %w", url, err)
			}
		}

		return nil
	}
}
